        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    if intersection_start <= intersection_end:
        return "YES" if is_prime(intersection_length) else "NO"
    else:
        return "NO"
