def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if len(numbers) < 2:
        return False

    numbers.sort()
    for i in range(len(numbers) - 1):
        if math.fabs(numbers[i + 1] - numbers[i]) <= threshold:
            return True

    return False
